CREATE INDEX attendance_verified_user_idx ON public.attendance(user_id,event_id) WHERE verified_at IS NOT NULL;
CREATE OR REPLACE FUNCTION public.get_participation_leaderboard(_category text DEFAULT 'total',_page integer DEFAULT 0) RETURNS TABLE(user_id uuid,roll_number text,full_name text,department text,total integer,tech integer,non_tech integer,events_count integer,rank bigint,total_count bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH totals AS (SELECT p.id AS user_id,p.roll_number,p.full_name,p.department,coalesce(sum(a.credits),0)::integer AS total,coalesce(sum(a.credits) FILTER(WHERE e.category='tech'),0)::integer AS tech,coalesce(sum(a.credits) FILTER(WHERE e.category='non_tech'),0)::integer AS non_tech,count(a.id)::integer AS events_count FROM public.profiles p LEFT JOIN public.attendance a ON a.user_id=p.id AND a.verified_at IS NOT NULL LEFT JOIN public.events e ON e.id=a.event_id GROUP BY p.id), ranked AS (SELECT t.*,rank() OVER(ORDER BY CASE _category WHEN 'tech' THEN t.tech WHEN 'non_tech' THEN t.non_tech ELSE t.total END DESC) AS rank,count(*) OVER() AS total_count FROM totals t) SELECT * FROM ranked ORDER BY rank,full_name,user_id LIMIT 50 OFFSET greatest(0,least(_page,100000))*50 $$;
REVOKE ALL ON FUNCTION public.get_participation_leaderboard(text,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_participation_leaderboard(text,integer) TO anon,authenticated;